using System.Collections.Generic;

namespace AncientWarfare3.content.figures
{
    internal static class HistoricalFigureCardBiographiesHan
    {
        public static void AddTo(IDictionary<string, string> pEntries)
        {
            pEntries.Add("chengjia_gongsun_shu",
                "公孙述在王莽末年据有蜀郡，凭借成都平原的财富和险要地势扩大割据势力。建武元年他在成都称帝，国号成家，并以白帝自居，任用延岑等人与刘秀争夺西南。建武十二年吴汉率东汉军攻破成都，公孙述战伤而死，成家政权随即灭亡。");
            pEntries.Add("chu_xiang_ji",
                "项羽（前232年—前202年），名籍，字羽，以字行，楚国下相（今江苏省宿迁市）人，秦朝末年至楚汉时期西楚的军事家、政治家，同时是西楚开国君主。楚国名将项燕之孙，七岁后随叔父项梁迁吴中，秦末民变期间在会稽郡（今江苏苏州）起兵反秦，受楚后怀王封为鲁公。前207年钜鹿之战中，项羽统率楚军五万大破秦军四十万，决定秦朝覆亡之势，秦朝最后一位君主子婴自降为「秦王」，不再称「皇帝」。项羽起兵三年，即率领山东六国诸侯灭秦，分封天下，政由羽出，自封「西楚霸王」，统治黄河及长江下游的梁楚九郡，年仅二十五岁。");
            pEntries.Add("han_aidi",
                "汉哀帝刘欣（前26年—前1年8月15日），出生于定陶（今山东省菏泽市定陶区），汉朝皇帝，在位6年，其正式谥号为「孝哀皇帝」，后世省略「孝」字称「汉哀帝」。刘欣是汉元帝孙，汉成帝弟定陶恭王刘康之子，母丁氏。汉哀帝于成帝驾崩后继位为帝，实权掌握在祖母太皇太后傅昭仪手中。哀帝为重振皇权而屡次诛杀在汉成帝时代提拔的大臣，尤其是以太皇太后王政君与王莽为首的王氏家族，将曲阳侯王根免去职务赶到封国，将成都侯王况废为庶人，并给母亲丁氏（丁太后）和妻子傅皇后的亲戚丁明、丁满、傅商、郑业等人加官晋爵。");
            pEntries.Add("han_andi",
                "汉安帝刘祜（94年—125年4月30日），东汉皇帝（106年9月21日－125年4月30日在位），汉章帝孙，清河王刘庆之子，在位19年，其正式谥号为「孝安皇帝」，后世省略「孝」字称「汉安帝」。他是汉章帝的孙子、当年被废太子清河王刘庆的长子，母左小娥。延平元年八月辛亥（106年9月21日），汉殇帝崩，12岁的他被外戚邓氏拥立为帝，承嗣汉和帝刘肇，改元永初。汉安帝即位后，仍由邓太后听政。");
            pEntries.Add("han_ban_chao",
                "班超（32年—102年），字仲升，右扶风平陵县（今陕西省咸阳市秦都区）人，东汉将领、外交家。是开拓和维持汉代与西域关系的重要人物。班超出生在文仕家庭，他是史学家班彪之子、《汉书》编撰者班固之弟。虽然出身如此，但其最大成就并不是文学相关： 而是选择投笔从戎，投身于稳固汉朝边疆的事业中，成为东汉名将，封定远侯。");
            pEntries.Add("han_ban_gu",
                "班固继承父亲班彪的史学事业，因私修国史一度入狱，获释后进入兰台继续编撰。《汉书》以纪传体系统记录西汉历史，成为中国第一部纪传体断代史。班固后来随窦宪北征并撰写《封燕然山铭》，窦氏失势后受牵连下狱，最终死于狱中。");
            pEntries.Add("han_ban_yong",
                "班勇（？—127年），字宜僚，右扶风平陵县（今陕西省咸阳市秦都区）人，东汉西域都护、定远侯班超第三子。汉和帝永元十三年（101年），班超派遣班勇随安息使者入洛阳觐见。在洛阳见到只闻其名声的姑母「曹大家」班昭，姑侄相见，喜极而泣，并请姑母代为向汉和帝请求让父亲班超及远征使节团的军眷归国。");
            pEntries.Add("han_cai_yong",
                "蔡邕（yōng）（132年或133年—192年），字伯喈（jiē），陈留圉人（今河南尉氏县）。东汉左中郎将、高阳侯，书法家，其父蔡陵，曾任徐州刺史，品行纯正，去世后的谥号为真定。少笃孝博学，善于绘画，又擅长音律，懂得天文、术数、灾变，几乎是问什麽都能对答如流的。校六经文字于熹平石经，又续写《东观汉记》。");
            pEntries.Add("han_cao_can",
                "曹参（？—前190年9月24日），字敬伯，泗水郡沛县（今江苏沛县）人，是西汉知名的将领，也是继萧何后的汉代第二位相国。反秦战争、楚汉战争和消灭异姓王中参与多次战役，立功最多，作战勇猛，成为汉军中的主要人物，曾经负伤七十处，攻下两国，一百二十二个县，俘虏诸侯王两名、高官十数人，封平阳侯。曹参战功虽高，论功时仍不及萧何，后因萧何推荐，继任相国。虽其与萧何关系不睦，但仍然依循萧的制度，实施无为而治，天下安定，世称「萧规曹随」。");
            pEntries.Add("han_chao_cuo",
                "晁（cháo）错（前200年—前154年3月6日），《史记》、《汉书》、《资治通监》本传作鼂错，颍川（今河南省禹州市）人，西汉初着名政论家。晁错年少时，从张恢学申不害、商鞅的法家学说；汉文帝时，为太常掌故，曾奉命从故秦博士伏生受《尚书》；成为一位儒法兼备的人物。之后，晁错上书说太子应深入了解申不害的言术，于是汉文帝就让晁错任太子家令，辅导太子刘启。晁错能言善辩，才能杰出，深得刘启的欣赏，被称为“智囊”。");
            pEntries.Add("han_chen_ping",
                "陈平在秦末投身反秦战争，先后依附魏王咎、项羽和刘邦，最终成为汉高祖的重要谋臣。他在楚汉战争中运用离间项羽与范增、解荥阳之围等计策，为刘邦夺取天下发挥关键作用。汉初他参与平定异姓诸侯王，吕后死后又与周勃诛灭诸吕并迎立汉文帝。");
            pEntries.Add("han_chen_tang",
                "陈汤（？—前6年），字子公，西汉山阳郡瑕丘县（今山东省兖州区东北）人，陈汤学识渊博，早年因家贫而向人乞讨。汉元帝时期，陈汤受荐举担任郎官，数次向朝廷请求出使外国，建昭三年，他与甘延寿共同出使西域，两人矫诏发兵诛灭郅支单于，返国后陈汤因功受封关内侯，食邑三百户，获赐黄金一百斤，擢升射声校尉。汉成帝初年，陈汤遭丞相匡衡弹劾而免职，又因上奏失实，被削除爵位降为一般士兵。后经大将军王凤推荐，担任从事中郎，幕府之事皆由其裁决。");
            pEntries.Add("han_chengdi",
                "汉成帝刘骜（前51年—前7年4月17日），字太孙。汉朝皇帝，其正式谥号为「孝成皇帝」，后世省略「孝」字称「汉成帝」，汉元帝长子，母孝元皇后王政君（王莽姑母）。汉成帝时王凤（舜的后人，汉成帝的舅舅）与许嘉（许平君的堂弟、孝成许皇后的父亲）并立为大司马车骑将军。后来许皇后失宠、赵飞燕及赵合德姐妹崛起，汉成帝没有男性后代，王凤一族逐渐控制了政权，王凤堂兄弟四人（王凤、王音、王商、王根）和侄子王莽相继为大司马或至大将军。");
            pEntries.Add("han_chongdi",
                "汉冲帝刘炳（汉安二年至永嘉元年正月初六戊戌日，即公元143年—145年2月15日），东汉皇帝（建康元年八月初六庚午日至永嘉元年正月初六戊戌日，即西元144年9月20日－145年2月15日在位），东汉第九位皇帝，在位仅五个月，享年还不满三周岁，其正式谥号为「孝冲皇帝」，后世省略「孝」字称「汉冲帝」。刘炳是汉顺帝的独子，他的母亲是虞美人，建康元年（144年）被立为太子。同年顺帝死后，两岁的刘炳于八月庚午登基，是为汉冲帝，改元“永嘉”。顺帝的皇后梁氏被尊为皇太后，临朝问政。");
            pEntries.Add("han_deng_yu",
                "邓禹（2年—58年），字仲华，南阳新野人。他最早以帝王功业勉励汉光武帝，向光武帝进言“延揽英雄，务悦民心，立高祖之业，救万民之命”，被认为有定策之功，光武帝恃之为萧何。邓禹参与了东汉统一战争，“既定河北，复平关中”，又推举了吴汉、贾复、寇恂等人，为汉光武帝平定天下立下汗马功劳，是「云台二十八将」之首。天下平定后，他与贾复两人率先配合刘秀“偃干戈，修文德”的政策，一同削减军队，推行儒学，为在“退功臣而进文吏”的局面下仍然能够参与讨论国家大事的三位列侯之一。");
            pEntries.Add("han_dong_zhongshu",
                "董仲舒（前2世纪—？），广川（今河北省景县）人，西汉时官员与学者，活跃于汉景帝至汉武帝时期，曾任《春秋》博士、江都国相、胶西国相。董仲舒向汉武帝呈上《天人三策》，提出儒家的治国蓝图，晚年闭门研究与着作，甚受朝廷重视，所作文章后世编为《春秋繁露》。董仲舒在儒学史上地位崇高，被视为汉代第一大儒，他建议罢黜百家，独尊儒术，促进汉代以至后世儒学的兴盛及主流化。然而董仲舒抑黜百家的主张，亦被今人批评为阻碍中国学术思想的发展。");
            pEntries.Add("han_dongfang_shuo",
                "东方朔（前154年—前93年），字曼倩，平原郡厌次县（今山东省德州市陵城区）人，西汉辞赋家、政治家、文学家。汉武帝时，朔上书自荐，言：“臣朔年二十二，长九尺三寸，目若悬珠，齿若编贝，勇若孟贲，捷若庆忌，廉若鲍叔，信若尾生，若此可以为天子大臣矣。”遂诏拜为郎，后任常侍郎、太中大夫等职。古代隐士，多避世于深山，而他却自称避世于朝廷。");
            pEntries.Add("han_dou_wu",
                "窦武（？—168年），字游平，右扶风平陵（今陕西咸阳西北）人。中国东汉末期外戚及大臣，官至大将军、录尚书事。出身扶风窦氏，司空窦融的玄孙，与刘淑、陈蕃合称为「三君」。因企图政变诛除宦官，兵败自杀。");
            pEntries.Add("han_dou_xian",
                "窦宪出身东汉外戚家族，是章德皇后窦氏之兄，早年凭借宫廷关系掌握权势并因横暴获罪。他为求自赎，于永元元年率军出塞，在稽落山大破北匈奴，追击至燕然山并由班固撰写铭文纪功。此后窦宪以大将军身份控制朝政、广置党羽，汉和帝联合宦官夺回权力后迫使他自杀，窦氏势力随之覆灭。");
            pEntries.Add("han_du_fu",
                "杜抚字叔和，是东汉犍为武阳人，以研习《韩诗》闻名于蜀地。他在乡里讲授经学，门生众多，使齐鲁经学传统得以在巴蜀传播。其著述与生卒资料保存不多，但地方经学教育和师承活动构成了他最明确的历史影响。");
            pEntries.Add("han_du_shi",
                "杜诗在东汉初年历任侍御史、南阳太守等职，以执法严明和地方治理著称。他在南阳兴修陂池、推广利用水力鼓风的水排，提高了冶铁生产效率并便利农具制造。当地百姓把他与西汉召信臣并称“前有召父，后有杜母”，肯定其改善民生的政绩。此卡侧重杜诗推广水排、改善冶铁生产和农具供应的技术治理成就。");
            pEntries.Add("han_du_zhi",
                "杜诗担任南阳太守期间整顿吏治、减轻徭役，并组织修复水利以扩大灌溉面积。他命人制作水排，以水力驱动冶铁鼓风设备，使铁器生产更省人力并服务农业。此卡侧重杜诗作为东汉地方官的行政身份，与另一张侧重技术推广的杜诗卡分别记录。此卡侧重杜诗出任南阳太守后整顿地方行政、兴修水利和减轻民间劳役的政绩。");
            pEntries.Add("han_duan_jiong",
                "段熲（jiǒng）（？—179年），字纪明，武威郡姑臧县（今甘肃武威市）人，东汉官员、军事家，曾任护羌校尉、平羌大将、司隶校尉、三公之首太尉等职位。典故“血战积石”就来自段颎，凉州武力豪族的代表人物之一，出自武威郡段氏。与皇甫规、张奂并称“凉州三明”。");
            pEntries.Add("han_fan_kuai",
                "樊哙早年在沛县以屠狗为业，随刘邦起兵后屡任先锋，是西汉开国功臣之一。鸿门宴上他持盾闯帐、斥责项羽并护送刘邦脱身，成为楚汉战争中的著名事件。汉朝建立后樊哙继续参与平定异姓诸侯王，晚年一度因吕氏姻亲关系遭刘邦猜忌，后获释善终。");
            pEntries.Add("han_feng_yi",
                "冯异（？—34年），字公孙，颍川父城（今河南宝丰东）人。冯异精通《左氏春秋》、《孙子兵法》，协助刘秀创建东汉政权，随刘秀安定河北，为刘秀偏将军，封应侯。在多年的行军作战中，冯异为刘秀建立东汉王朝立下了汗马功劳。但冯异谦逊，从不夸己功，诸将并坐论功，他常避于大树下，被誉为大树将军。");
            pEntries.Add("han_gan_yanshou",
                "甘延寿，字君况，西汉北地郡郁郅县（今属甘肃省庆城县）人。甘延寿年轻时由于是清白人家的子弟，又善于骑射，故而受选拔为羽林军的骑士，在投石、拔距等军事训练中，成绩大幅超越周围的同僚，还曾经翻越过羽林军营房的亭楼，身手矫捷又孔武有力，因此被擢升为郎官，其后他又通过徒手搏斗的测验，成为期门郎，凭藉自身的才能勇气得到皇帝的宠幸。甘露元年，甘延寿以期门郎的身分与谒者竺次作为副使，护送冯嫽西行前往乌孙，册立元贵靡为大昆弥，乌就屠为小昆弥，赐予二者印绶。");
            pEntries.Add("han_gaozu",
                "汉高祖刘邦（前256年或前247年—前195年6月1日），字季，原名刘季，沛丰邑中阳里（今江苏省丰县）人，中国秦末汉初的军事家、政治家，汉朝开国皇帝，也是中国历史上第一位平民阶级出身的皇帝。秦末世乱之际，其参与以楚国为首的反秦起义，成为诸侯之一。在楚汉战争中，刘邦击败西楚霸王项羽，统一了自秦朝灭亡后的天下，于公元前202年在定陶泛水之阳（今山东省菏泽市定陶）称帝，定都长安，建立汉王朝。");
            pEntries.Add("han_geng_yan",
                "耿弇（yǎn）（3年—58年），字伯昭，扶风茂陵人，上谷太守耿况之子。耿弇劝説父亲耿况支持刘秀，协助刘秀获得上谷、渔阳等地的精兵突骑，转战各地，22岁便被光武帝封为大将军，后受命率兵东征，以围城打援、声东击西、以逸待劳等计策击破张步，一举平定齐地。耿弇一生征战，“平郡四十六，屠城三百，未尝挫折”，是汉光武帝平定天下的功臣，为云台二十八将的第四位。");
            pEntries.Add("han_guan_ying",
                "灌婴 （？—前176年），睢阳（今河南商丘）人。汉朝开国功臣，官至太尉、丞相，封颍阴侯，谥号为懿侯。灌婴原本是在睢阳卖布帛的商人。");
            pEntries.Add("han_guangwu",
                "汉光武帝刘秀（前5年1月15日—57年3月29日），字文叔，南阳郡蔡阳县人（今湖北省枣阳市），东汉开国皇帝，25年8月5日至57年3月29日在位。刘秀为汉高祖刘邦的九世孙，景皇帝刘启的七世孙，长沙定王刘发之后，出身于南阳郡的地方豪族。新朝末年国家动荡，各地寇盗蜂起。地皇三年（22年壬午年），刘秀与其兄长刘演在宛（今河南省南阳市）起兵。");
            pEntries.Add("han_guo_kui",
                "郭躬（1年—94年），字仲孙，颍川阳翟（今河南禹州市）人，东汉政治人物。郭躬的父亲郭弘有审理刑事案件三十年的经验，执法公平。他年少时继承父亲的事业，讲授法律，有几百名学生。后来做了郡吏，被公府征召。");
            pEntries.Add("han_han_xin",
                "韩信（前231年—前196年），淮阴人，西汉开国功臣，与张良，萧何并称为汉初三杰；又与彭越、英布并称为汉初三大名将。被后人称为“兵仙”，同时萧何称其为「国士无双」、蒯彻称其为「功高无二，略不世出」。汉朝至东晋期间许多人将韩信与战国末年秦国名将白起合称「韩白」。韩信平民出身，家庭贫困，早年寄人篱下，曾受过“胯下之辱”。");
            pEntries.Add("han_hedi",
                "汉和帝刘肇（79年—106年2月13日），东汉皇帝（88年4月9日－106年2月13日在位），在位17年，得年仅27岁，其正式谥号为「孝和皇帝」，后世省略「孝」字称「汉和帝」，他是汉明帝孙，章帝第四子，母贵人梁氏，死后庙号穆宗（后于汉献帝初平元年除去庙号），葬于慎陵。由于年幼即位，权力被外戚所挟制，及长后利用宦官权力扫除外戚威胁得以亲政。这开始了东汉戚宦相争的恶性循环。但和帝本人亲政后励精图治，四海昇平，是东汉明章二帝后获评价最高的皇帝。");
            pEntries.Add("han_houshao",
                "西汉后少帝刘弘（前196年—前180年11月14日），原名山，曾用名义，汉朝皇帝，前184年6月15日-前180年11月14日在位，汉惠帝之四子。汉朝大臣诛灭诸吕之后，刘弘被称是其他人的私生子，被罢黜后旋即处死，后世史称「后少帝」。前187年四月廿八（6月5日），被封为襄成侯。前186年七月，恒山王刘不疑死后，刘山于七月廿七接封为恒山王（后世为避汉文帝刘恒讳，改称“常山王”），并改名刘义。");
            pEntries.Add("han_huandi",
                "汉桓帝刘志（132年—168年1月25日），东汉皇帝（146年8月1日－168年1月25日在位），其正式谥号为「孝桓皇帝」，后世省略「孝」字称「汉桓帝」，他是汉章帝曾孙，河间孝王刘开之孙，蠡吾侯刘翼之子，在位21年。他在位时，东汉国力逐渐衰落，为黄巾之乱埋下伏笔。刘志于132年出生于蠡吾（今河北省博野县）原袭爵为蠡吾侯。146年，外戚梁冀毒死九岁的汉质帝。");
            pEntries.Add("han_huangfu_gui",
                "皇甫规（104年—174年），字威明，安定郡朝那县（今宁夏回族自治区固原市彭阳县）人，东汉时期军事家、学者。爷爷是度辽将军皇甫棱、父亲是扶风都尉皇甫旗。皇甫规与段熲、张奂并称“凉州三明”。");
            pEntries.Add("han_huidi",
                "汉惠帝刘盈（前211年或前210年—前188年9月26日），汉朝将盈避讳为满，汉朝开国皇帝汉高祖刘邦和皇后吕氏之子。汉朝皇帝，于前195年6月26日—前188年9月26日在位，在位7年，其正式谥号为「孝惠皇帝」。惠帝在位期间，以温柔敦厚的个性，积极推行黄老学说，注重国家的休养生息和无为而治，解除文化专制政策，修筑长安城，为巩固西汉政权，安定社会，促进经济文化的发展，作出了一定的贡献。惠帝在位时朝政深受母亲吕后干预，由于吕后具有压制性的影响力，并成为实际统治者，因此司马迁《史记》未设「孝惠本纪」，反而设《吕后本纪》。");
            pEntries.Add("han_huo_guang",
                "霍光（？—前68年4月21日），字子孟，西汉河东郡平阳县（今山西省临汾市）人，政治家，麒麟阁十一功臣之首，名将霍去病异母弟，昭帝上官皇后外祖父，宣帝霍皇后之父。先后任郎官，曹官、侍中、奉车都尉、光禄大夫、大司马、大将军等职位，封博陆侯，谥号为宣成，是以又被尊称为博陆宣成侯。历经汉武帝、汉昭帝、汉废帝、汉宣帝四朝，期间曾主持废立昌邑王。宣帝地节二年霍光去世，过世后第二年霍家因谋反被族诛。");
            pEntries.Add("han_huo_qubing",
                "霍去病是汉武帝时期抗击匈奴的名将，也是卫青的外甥，十八岁便以骠姚校尉身份随军出塞。他两次河西之战重创匈奴并夺取河西走廊，随后在漠北之战深入敌境，封狼居胥后凯旋。霍去病主张主动追击、长途奔袭，二十三岁早逝，其战果帮助西汉打通通往西域的战略通道。");
            pEntries.Add("han_jia_yi",
                "贾谊（前200年—前168年），雒阳（今河南省洛阳市东）人，西汉政论家、思想家、文学家。由于是知名的学者，人称贾生、当过长沙王太傅，故世称贾太傅、贾长沙。其政论文《过秦论》、《论积贮疏》、《治安策》等，在历史上有很高的地位。");
            pEntries.Add("han_jingdi",
                "汉景帝刘啓（前188年—前141年3月9日），为汉朝皇帝（前157年7月14日－前141年3月9日在位），在位16年，享年48岁，其正式谥号为「孝景皇帝」，后世省略「孝」字称「汉景帝」，景帝后元三年正月甲子（前141年3月9日）崩于未央宫，二月癸酉（3月18日）葬于阳陵（今陕西高陵县西南）。为汉文帝刘恒长子，母窦皇后。他在位期间，主要是削诸侯封地，平定七国之乱，巩固中央集权，勤俭治国，发展生产，他和其父亲文帝的统治时期合称文景之治，为中国自大一统以来的首个太平盛世。");
            pEntries.Add("han_li_gu",
                "李固（93年—147年），字子坚，汉中郡南郑县人，东汉太尉，司徒李合之子。少有奇表，好学交贤，后数次以恩信平叛，推举良臣。于皇储之争上，两次反对外戚大将军梁冀立幼不立长，被梁冀陷害致死。");
            pEntries.Add("han_li_guang",
                "李广（前187年至前179年期间—前119年），陇西成纪人，西汉时武将。一生与匈奴交战四十余年，大小七十余战，匈奴人畏其英勇，称之为「飞将军」。李广的先祖是秦朝将领李信，将门世家出身。汉文帝十四年（前165年）从军。");
            pEntries.Add("han_li_yan",
                "李延年以歌唱、作曲和舞乐才能受到汉武帝赏识，进入宫廷后参与乐府音乐活动。他创作的新声与协律工作推动西汉宫廷礼乐的发展，其“北方有佳人”歌辞又促成妹妹李夫人得到武帝宠爱。李氏家族后来因外戚和军功进入权力中心，李延年的命运也随宫廷关系变化而起落。");
            pEntries.Add("han_li_ying",
                "李膺（110年—169年），字元礼。颍川襄城（今河南省襄城县）人。东汉名士，第二次党锢之祸受害者。李膺的祖父李修在汉安帝时期曾任太尉，父亲李益曾任赵国的国相。");
            pEntries.Add("han_li_zhang",
                "李章被卡库收录为东汉边郡军职人物，主要承担骑兵调度、烽燧联络和军粮转运等事务。他所处的边防体系依靠郡县、障塞与驻军协同，日常后勤往往决定远征和守备能否持续。现存传记材料较少，本卡据东汉军政身份独立记录，不采用百科中明代同名官员的生平。");
            pEntries.Add("han_lingdi",
                "汉灵帝刘宏（156年—189年5月13日），东汉皇帝（168年2月17日－189年5月13日在位），在位22年，葬于汉文陵，其正式谥号为「孝灵皇帝」，后世省略「孝」字称「汉灵帝」。刘宏本封解渎亭侯，为承袭其父刘苌的爵位。他是汉章帝的玄孙，汉桓帝的堂侄。永康元年桓帝崩，由于桓帝无子，城门校尉窦武主持商讨立嗣问题，召侍御史刘儵访查宗室中有否贤明之人，而刘儵推荐了刘宏。");
            pEntries.Add("han_lu_zhi",
                "吕氏（前241？—前180年8月18日），字娥姁，一说名雉。通称吕后，或称汉高后、吕太后、高皇后。东汉时光武帝追尊薄太后为高皇后，追废吕后为高后。山东单父（今山东省菏泽市单县）人，为汉高祖刘邦任亭长时所娶元配妻子。");
            pEntries.Add("han_ma_yuan",
                "马援（前14年—49年），字文渊，扶风郡茂陵（今陕西省兴平市东北）人，东汉军事家。汉光武帝时，拜为伏波将军，封新息侯，世称马伏波。出身官宦世家，马援的祖父马宾在汉宣帝时期以郎持节，号“使君”。马援身长七尺五寸，长相俊美，担任扶风郡（今陕西兴平东南）督邮的时候，当时已是新朝王莽当政的时期。");
            pEntries.Add("han_mei_cheng",
                "枚乘（？—前140年），字叔，淮阴（今属江苏省淮安市）人，西汉辞赋家、文学家。枚乘，字叔，淮阴（今属江苏省淮安市）人，西汉辞赋家、文学家。枚乘曾为吴王刘濞的郎中，曾劝吴王不要谋反，不听。");
            pEntries.Add("han_mingdi",
                "汉明帝刘庄（28年6月15日—75年9月5日），原名刘阳，字子丽，东汉皇帝，在位十八年。谥「孝明皇帝」，后世省略「孝」字称「汉明帝」，庙号显宗。汉光武帝刘秀的第四子，母亲为光烈皇后阴丽华。");
            pEntries.Add("han_peng_yue",
                "彭越（前2世纪？—前196年），字仲，昌邑（今山东省菏泽市巨野县）人，秦末汉初的军事政治人物，与韩信、英布并称汉初三大名将，西汉开国功臣，封梁王。后在消灭异姓王时，汉高祖命其讨伐阳夏侯陈豨，彭越出力甚少，后遭到高祖整肃、流放，途中向吕后求情，却反遭吕后处死并灭族。彭越屍体遭到醢刑，剁为肉酱，朝廷用这些肉酱来恫吓各诸侯王。");
            pEntries.Add("han_pingdi",
                "汉平帝刘衎（kàn）（公元前9年—6年2月3日），原名刘箕子，后改名衎，汉朝皇帝（公元前1年10月17日－公元6年2月3日在位），其正式谥号为「孝平皇帝」，后世省略「孝」字称「汉平帝」。汉平帝刘（公元），原名刘箕子，后改名衎，汉朝皇帝（公元前1年10月17日－公元6年2月3日在位），其正式谥号为「孝平皇帝」，后世省略「孝」字称「汉平帝」。刘衎父亲是汉元帝之子、中山孝王刘兴，母亲卫姬。幼年体弱多病，身体发青，可能患有现代医学所谓的青紫型先天性心脏病。");
            pEntries.Add("han_qianshao",
                "西汉前少帝（？—前184年6月15日），本名不详，前188年9月27日-前184年6月15日在位，汉朝皇帝，史称「前少帝」。历史记录中未记载其名字，“刘恭”一名可能来自1909年近代日本历史着作中似把“刘某”一词做的误写，使钱穆《国史大纲》等史作亦采用此名。另有明代古书记载其名字为刘智。");
            pEntries.Add("han_ren_shang",
                "任尚（？—119年1月22日），东汉将领。最初为邓训护羌府长史，有战功。永元年间，窦宪出屯凉州，请为司马，永元三年（91年）二月，击北匈奴于金微山，大破之，后迁戊己校尉。");
            pEntries.Add("han_ruzi",
                "刘婴（5年—25年2月），西汉末代君主、皇太子（6年4月17日－9年1月15日为皇太子，未正式即位），号孺子，故称孺子婴，是汉宣帝的玄孙、楚孝王刘嚣曾孙、广戚炀侯刘勳孙、广戚侯刘显子。元始五年（5年），汉平帝死后，因平帝与王皇后（王莽之女）及诸妃皆无子嗣，且平帝祖父汉元帝一脉已无存活男嗣，帝位继承陷入困境，朝臣遂从平帝曾祖父汉宣帝的后裔中遴选继位者。此时汉宣帝的曾孙辈中虽有五十三人健在，然皆已成年，把持朝政的王莽深忌此况。为便于掌控朝局，他执意择立幼主，遂以“兄弟不得相继”为由（尽管数年前平帝曾以从弟身份继承哀帝之位），转而考量宣帝玄孙辈共二十三人——此辈皆系尚在襁褓或初学步的婴幼童。");
            pEntries.Add("han_sang_hongyang",
                "桑弘羊出身洛阳商人家庭，因善于计算和理财在汉武帝朝进入财政中枢。他主持盐铁专卖、均输平准、统一铸币和酒类专营，以国家经营收入支撑对匈奴战争及边疆屯田。汉昭帝时他在盐铁会议上为武帝经济政策辩护，后卷入燕王刘旦与上官桀谋反案，被霍光处死。");
            pEntries.Add("han_shangdi",
                "汉殇帝刘隆（105年10月或11月—106年9月21日），汉和帝幼子，养于民间，东汉第五位皇帝（106年在位），其正式谥号为「孝殇皇帝」，后世省略「孝」字称「汉殇帝」。汉殇帝是中国历史上即位年龄最小、寿命最短的皇帝。刘隆系汉和帝刘肇与身份不详的宫人所生之皇子。和帝在世的时候，生了许多皇子，大都夭折。");
            pEntries.Add("han_shaodi",
                "东汉后少帝刘辩（176年—190年3月6日，熹平五年－初平元年正月十二癸丑日），东汉皇帝（光熹元年四月十三戊午日至昭宁元年九月初一甲戌日，即公元189年5月15日－189年9月28日在位），是汉灵帝刘宏与皇后何氏的独生儿子，即是嫡长子，后遭董卓废黜。刘辩在灵帝驾崩后继位为帝，由于年幼，实权掌握在临朝称制的母亲何太后和母舅大将军何进手中。少帝在位时期，东汉政权已经名存实亡，他即位后不久即遭遇以何进为首的外戚集团火并以十常侍为首的内廷宦官集团，为了避祸被迫出宫，回宫后又受制于以“勤王”为名进京的西北军阀董卓，之后被废为弘农王，成为东汉唯一一位被废黜的皇帝，其同父异母弟陈留王刘协继位为帝，是为汉献帝。");
            pEntries.Add("han_shundi",
                "汉顺帝刘保（115年—144年9月20日），东汉皇帝（125年12月16日－144年9月20日在位），其正式谥号为「孝顺皇帝」，后世省略「孝」字称「汉顺帝」。刘保出生后，生母李氏就被皇后阎姬毒杀。刘保从小学习孝经章句，很得邓太后欣赏，认为他可以继承大统。永宁元年（120年），身为汉安帝独子的刘保被立为皇太子。");
            pEntries.Add("han_sima_qian",
                "司马迁（前145年—前86年？），字子长（cháng），世称“史迁”、“太史公”、“历史之父”，龙门（今陕西韩城）人，西汉史学家和文学家。司马迁所撰写的《史记》被公认为是中国史书的典范，创作《史记》的过程中，秉承了他对史实真实性和客观性的坚持，他的史学方法严谨，以事实为依据，不涉及个人观点，被誉为「史家之镜」。首创的纪传体撰史方法为后来历代正史所传承，被后世尊称爲史圣，又因曾任太史令，故自称太史公。");
            pEntries.Add("han_sima_xiangru",
                "司马相（xiāng）如（前179年—前117年），本名犬子，因慕蔺相如之人，故更名相（xiāng）如，字长（zhǎng）卿（蔺相如官至上卿），蜀郡（今四川省）成都人，一说为四川蓬安县人。西汉辞赋家、政治家、文学家。其代表作品为《子虚赋》、《上林赋》。作品词藻富丽，结构宏大，使他成为汉赋的代表作家，后人称之为赋圣。");
            pEntries.Add("han_wang_ba",
                "王霸是东汉开国将领，早年在颍川追随刘秀，长期参与河北和关中方向的统一战争。他善于守备与野战，曾在险要地区抗击苏茂、周建等敌军，并负责稳定黄河以北的军事局势。刘秀称帝后王霸受封淮陵侯，列入云台二十八将，其军功服务于东汉重建。");
            pEntries.Add("han_wang_ji",
                "王吉是西汉经学家和官员，曾任昌邑王刘贺属官，多次劝谏其约束游猎和荒纵行为。汉宣帝时期他被征入朝廷，以崇尚礼义、重视选贤和反对奢侈提出政见。他与贡禹交往密切，“王阳在位，贡公弹冠”的故事成为士人相互援引和共同进退的典故。");
            pEntries.Add("han_wang_mang",
                "王莽（前45年—23年10月6日），字巨君，魏郡元城贵乡（今河北邯郸大名县东）人，篡夺汉朝自立，不被承认的僭主，是西汉末年政治人物、外戚及权臣。他最终以「假皇帝」（代理皇帝）身份登基并建立新朝，自称“皇帝”。称帝后的王莽大举推行向周朝看齐的复古改革，引发社会动荡，再加上黄河改道等天灾，以致各地豪强纷起，亦有民变发生，新朝仅14年就被推翻，王莽也被叛军所杀。文献记载王莽身高七尺五寸（大约173公分）。此卡以王莽作为西汉外戚、辅政大臣并逐步取得朝权的臣僚阶段收录。");
            pEntries.Add("han_wei_qing",
                "卫青由平阳侯府骑奴进入宫廷，因姐姐卫子夫受宠而获任用，但其军功主要建立在多次对匈奴作战之中。他从龙城之战开始七次出击，收复河套、设置朔方郡，并在漠北之战与霍去病分道深入草原，迫使匈奴主力北退。卫青官至大司马大将军，治军谨慎且能约束部属，是汉武帝前期由守转攻战略的核心统帅。");
            pEntries.Add("han_wendi",
                "汉文帝刘恒（前203年—前157年），中国汉朝（西汉）初期皇帝，于前180年至前157年在位，共23年，庙号太宗，正式谥号为「孝文皇帝」，后世省略「孝」字称为「汉文帝」。其系汉高祖刘邦第四子，母亲是汉高祖薄姬（即薄太后），墓葬是汉霸陵（位于今陕西省西安市灞桥区白鹿原）。汉文帝是中国历史上第一位经由推选出来的皇帝，也是一位贤良、节俭、恤民及治国有方的君主，与其子汉景帝共同创造了中国历史上大一统时代的首个盛世「文景之治」。");
            pEntries.Add("han_wudi",
                "汉武帝刘彻（前156年－前87年），中国汉朝（西汉）皇帝，于公元前141年至前87年在位，共在位54年。汉武帝为汉景帝刘启第十子，母孝景王皇后。其少时先被封为胶东王，七岁被立为太子，十六岁登基，其在位期间首次使用年号纪年。汉武帝是中国历史上最为着名和最富争议的帝王之一，其一生以强皇权、整饬吏治、削藩立制与对外扩张为主轴，既塑造了汉帝国空前的政治动员与疆域格局，也留下了沉重的战争成本与晚年政治灾变的复杂遗产。");
            pEntries.Add("han_xiandi",
                "汉献帝刘协（181年4月2日—234年4月21日），字伯和，司隶雒阳人。刘协是东汉皇帝，汉灵帝刘宏之子、后少帝刘辩异母弟。189年至220年在位，是东汉乃至汉朝的最后一任皇帝。根据《后汉书》记载，刘宏因为认为刘协像自己，取名“协”。");
            pEntries.Add("han_xiao_he",
                "萧何原为沛县主吏，刘邦起兵后负责收集秦朝律令、户籍和地理档案，为新政权掌握关中资源奠定基础。楚汉战争期间他留守关中，持续征发兵员粮饷，并月下追回韩信、力荐其为大将。汉朝建立后萧何主持制定制度、营建长安，晚年又协助吕后处置韩信，官至丞相并列汉初三杰。");
            pEntries.Add("han_xuandi",
                "汉宣帝刘询（前91年—前48年1月10日），原名刘病已，字次卿，即位九年后改名询，汉朝皇帝（前74年9月10日－前48年1月10日在位），其正式谥号为「孝宣皇帝」，后世省略「孝」字称「汉宣帝」。汉武帝的曾孙，戾太子刘据的长孙，史皇孙刘进的长子，生母为王翁须。宣帝长久秉持“王霸之道杂之”的政治策略。他一方面沿续霍光时期的韬光养晦，继续减轻各种税赋和民众的负担，即所谓的“王道”；同时又厉行法家政策，整顿吏治，即所谓的“霸道”。");
            pEntries.Add("han_yan_zhu",
                "严助（《史记》称庄助），字义兴，为西汉中早期会稽郡吴县（今江苏省苏州市）人，严忌之子，也有人说他是严忌的族子。后拜会稽太守，复留为侍中。严助在世时姓庄，在他去世很多年后，《汉书》为避东汉明帝刘庄的讳，把庄助等庄姓的人改称严姓。严助是着名辞赋家，有辞赋三十五篇。");
            pEntries.Add("han_yang_biao",
                "杨彪出身弘农杨氏，家族自杨震起四世官至太尉，是东汉末年的重臣。他反对董卓迁都长安，又在李傕、郭汜控制朝廷时设法保护汉献帝，长期卷入军阀挟持下的中枢政治。曹操掌权后杨彪逐渐退居，其子杨修被杀更使他拒绝出仕曹魏。");
            pEntries.Add("han_yang_zhen",
                "杨震是东汉弘农杨氏的重要人物，早年长期讲学，因通晓经籍而被称为“关西孔子杨伯起”。他任荆州刺史、东莱太守时拒收故吏王密夜间赠金，以“天知、神知、我知、子知”说明清廉不可欺。官至太尉后杨震屡次反对外戚与宦官干政，遭樊丰等人诬陷罢免，最终在归乡途中饮鸩而死。");
            pEntries.Add("han_ying_bu",
                "英布因秦刑受黥而又称黥布，秦末率骊山刑徒起兵，归附项梁、项羽后以勇战受封九江王。楚汉战争中他与项羽决裂，转而协助刘邦牵制楚军，汉朝建立后改封淮南王，与韩信、彭越并称汉初三大名将。韩信、彭越相继被杀后英布因惧祸举兵反汉，败于刘邦亲征，逃往江南后被长沙王部下诱杀。");
            pEntries.Add("han_yuandi",
                "汉元帝刘奭（shì）（前75年—前33年7月8日），汉朝皇帝，其正式谥号为「孝元皇帝」，后世省略「孝」字称「汉元帝」。汉宣帝长子，生于民间，母恭哀皇后许平君。宣帝死后继位，在位16年（前48年－前33年）。");
            pEntries.Add("han_zhang_heng",
                "张衡（78年—139年），字平子，南阳郡西鄂县（今河南省南阳市南召县南）人，东汉士大夫、天文学家、地理学家、数学家、科学家、发明家及文学家，官至太史令、侍中、尚书。张衡一生成就不凡，曾制作以水力推动的浑天仪、发明能够探测震源方向的地动仪和指南车、发现日食及月食的原因、绘制记录2,500颗星体的星图、计算圆周率准确至小数点后一个位、解释和确立浑天说的宇宙论；在文学方面，他创作了《二京赋》及《归田赋》等辞赋着作，拓展了汉赋的文体与题材，被列为「汉赋四大家」之一。他开创了七言古诗的诗歌体裁，对中华文化有巨大贡献。");
            pEntries.Add("han_zhang_liang",
                "张良出身韩国贵族，秦灭韩后曾在博浪沙策划刺杀秦始皇，失败后隐匿下邳并研习兵法。秦末他追随刘邦，在入关约法、鸿门宴脱险、争取韩信彭越和垓下合围等关键决策中发挥作用。汉朝建立后张良受封留侯，却逐渐淡出权力斗争，以辟谷养生自处，后世与萧何、韩信并称汉初三杰。");
            pEntries.Add("han_zhang_qian",
                "张骞（前175年2月25日—前114年4月25日），字子文，汉中郡成固（今陕西省城固县）人，西汉旅行家、外交家、探险家，丝绸之路的开拓者。奉汉武帝之命，从长安出发出使西域，两次被匈奴军队俘虏囚禁，历时13年终于逃回长安复命，从而成功开拓了丝绸之路。因此伟大功绩，汉武帝封张骞为博望侯（取“广博瞻望”之意），故又称张博望，封地博望（今中国河南省方城县博望镇）。");
            pEntries.Add("han_zhangdi",
                "汉章帝刘炟（dá）（57年—88年4月9日），汉明帝刘庄第五子，东汉皇帝（75年9月5日—88年4月9日在位），其正式谥号为「孝章皇帝」，后世省略「孝」字称「汉章帝」，庙号肃宗。建武中元二年（57年）二月，其父刘庄即位。同年，刘炟出生，为汉明帝刘庄第五子。当时，父亲明帝宠爱的马贵人无子，于是明帝把刘炟交给马贵人抚养。");
            pEntries.Add("han_zhao_chongguo",
                "赵充国（前137年—前52年），字翁孙，西汉时期的军事将领和官员。他原为陇西郡上邽县人，后迁居至金城郡令居县。赵充国为人沉着勇武，富有谋略，通晓匈奴和西羌的习性。他出身于官宦世家，年轻时学习兵法。");
            pEntries.Add("han_zhaodi",
                "汉昭帝刘弗陵（前94年—前74年6月5日），汉朝皇帝（前87年－前74年在位），其正式谥号为「孝昭皇帝」，后世省略「孝」字称「汉昭帝」，汉武帝幼子，母亲钩弋夫人。昭帝身高八尺二寸（约1.89米）。据说钩弋夫人怀孕14个月才生下刘弗陵，大臣们都以为尧帝降生，纷纷恭祝武帝。武帝老年得子，更是爱不释手，常说像自己。");
            pEntries.Add("han_zhidi",
                "汉质帝刘缵（138年—146年7月26日），一名续，东汉皇帝，145年3月6日－146年7月26日在位，时间仅1年4个月。谥号为「孝质皇帝」，后世省略「孝」字称「汉质帝」。当时梁冀一家专权，朝政腐败、吏治不修，威势横行朝廷和宫外；大臣们害怕梁冀的威势，不敢抗命。质帝虽年幼，但聪明伶俐，不堪梁冀的专横跋扈，曾在朝会见大臣时，当面对梁冀说：「此跋扈将军也！」梁冀听罢，大为反感，便命手下在质帝的汤饼里下毒弑君。");
            pEntries.Add("han_zhong_jun",
                "终军（前133年—前112年），字子云，西汉济南历城（今属山东省济南市历城区仲宫镇）人，汉朝政治家。以博闻强记、能言善辩、文笔优美闻名于郡中，十八岁被选为博士弟子，上书评论国事，汉武帝刘彻封谒者给事中，后擢升谏大夫，武帝派使者去匈奴，自请曰：“军无横草之功，得列宿卫，食禄五年。边境时有风尘之警，臣宜被坚执锐，当矢石，启前行。”并曰：“臣愿尽精厉气，奉佐明使，划吉凶于单于之前”。");
            pEntries.Add("han_zhou_bo",
                "周勃随刘邦从沛县起兵，以军功参加灭秦和楚汉战争，汉朝建立后封绛侯。他平定韩王信、陈豨等叛乱，并被刘邦评价为能够安定刘氏天下的重臣。吕后死后周勃与陈平诛灭诸吕、迎立汉文帝，后来虽一度下狱，仍成为汉初功臣辅政的代表。");
            pEntries.Add("han_zhu_fu",
                "朱浮（约前6年—66年），字叔元，沛国萧县（今安徽萧县西北）人。朱浮跟随汉光武帝担任大司马主簿。后来转任偏将军，跟随刘秀破邯郸王郎。东汉建立，朱浮任大将军、幽州牧，驻守蓟城（今北京市），讨伐平定北方。");
            pEntries.Add("han_zhu_maichen",
                "朱买臣，字翁子，一作翁之，会稽郡吴县（今江苏苏州）人，中国西汉中期政治人物。早年家贫，后为严助所荐，得到汉武帝的赏识，任为中大夫。不久免职，后又复起，被任命为会稽太守，负责与韩说等征讨东越。东越平定后，朱买臣获封为主爵都尉。");
            pEntries.Add("xin_wangmang",
                "王莽（前45年—23年10月6日），字巨君，魏郡元城贵乡（今河北邯郸大名县东）人，篡夺汉朝自立，不被承认的僭主，是西汉末年政治人物、外戚及权臣。他最终以「假皇帝」（代理皇帝）身份登基并建立新朝，自称“皇帝”。称帝后的王莽大举推行向周朝看齐的复古改革，引发社会动荡，再加上黄河改道等天灾，以致各地豪强纷起，亦有民变发生，新朝仅14年就被推翻，王莽也被叛军所杀。文献记载王莽身高七尺五寸（大约173公分）。此卡以王莽建立新朝并实施王田、币制等改革后的皇帝身份收录。");
            pEntries.Add("zhong_hou_shu",
                "袁术（？—199年），字公路，汝南郡汝阳县（今河南商水）人，出身于官宦门阀，袁逢之子，袁基、袁绍之弟。东汉末年的军阀，官至左将军。最初以南阳作为领地，之后立足淮南僭号称帝，自立为仲氏政权，却得不到支持，反遭各方势力围攻及孤立，在位两年半屡次兵败，最终因悲愤吐血而死。");
        }
    }
}
